\end{corollary}

\subsection{Tressl signature-alternative in simply exponential o-minimal fields}\label{ssec:first_application}
In this subsection we show how Proposition~\ref{prop:height_over_absorbed}, can be used to partially answer a problem posed in \cite{tressl2005model}. Our setting will be the one of an elementary extension $\bE \prec \bE_*\models T$ of models of an \emph{exponential} o-minimal theory $T$.

In \cite[Def.~3.16]{tressl2005model}, Tressl considers the following condition on a unary type $p=\tp(x/\bE)$ over $\bE$: $p$ satisfies the \emph{signature alternative} if it is either non-symmetric, or
\begin{enumerate}
    \item $\Br(x/\bE)(\bE)$ is cofinal in $\Br(x/\bE)(\bE\langle x\rangle)$, that is, $\bE\langle x \rangle$ does not realize the cut above $\Br(x/\bE)(\bE)$;
    \item if $y$ is the realization of such cut, i.e.\ if $y \in \Br(y/\bE)(\bE_*)$ and $y>\Br(x/\bE)(\bE)$, then $\Br(\log y/\bE)$ is cofinal in $\Br(\log y/\bE)(\bE \langle y \rangle)$.
\end{enumerate}

Note that if (1) above is satisfied by all types over $\bE$, then all types over $\bE$ satisfy (2) as well. We point out the following immediate Corollary of Proposition~\ref{prop:breadth-ortho} and 

\begin{corollary}\label{cor:finite_hight_and_br_ortho}
    If $x \in \bE_* \setminus \bE$ is symmetric, and all $y \in \bE \langle x\rangle$ have finite height in $(\bE\langle x \rangle, \cO_*^-, \partial_x)$ with $\cO_*^-=\CH(\bZ)$, then $\Br(x/\bE)(\bE)$ is cofinal in $\Br(x/\bE)(\bE\langle x\rangle)$.
    \begin{proof}
        By Proposition~\ref{prop:breadth-ortho}(1) we have for all $y \in \bE \langle x \rangle$ that if $y \in \Br(x/\bE)(\bE\langle x\rangle)\setminus \CH(\Br(x/\bE)(\bE))$, then
        \[ \lder_x^k(y)\in \Br(x/\bE)(\bE\langle x\rangle)\setminus \CH(\Br(x/\bE)(\bE)) \quad \text{for all}\; k \in \bN.\]
        But then this would imply that $\val_{\cO_*^-}(\lder^k y) \notin \val_{\cO_*^-}(\bE)$ and $y$ would have infinite height.
    \end{proof}

ref_dict.introthm:transserial_char:
\begin{thmA}\label{introthm:transserial_char}
    The following are equivalent for an exponential o-minimal theory $T$:
    \begin{enumerate}[ref=(\arabic*)]
        \item\label{introthmenum:transserial} $T$ is transserial;
        \item\label{introthmenum:exp-bdd_gne_at_special} $T$ is exponentially bounded and for all $(\bE, \cO) \models T_\convex$, all $\cO < b <\bE^{>\cO}$, for every $y \in \bE \langle b \rangle$ there is a $\bE$-definable gne $g$, such that $y \equiv_\bE g(b)$;
