Assume $1<p<\frac{n+2s}{n-2s}$, $f$ satisfies 
\begin{equation}\label{growth f}
 f(x,t)\le C_0(1+t^p)
\end{equation}
uniformly for all $x$ in $\Omega$, and 
\begin{equation}\label{lim f}
 \lim _{t\to\infty}\frac{f(x,t)}{t^p} = K(x),
\end{equation}
 where $K(x)\in (0,\infty)$ is uniformly continuous and $K(\infty):=\lim _{|x|\to\infty }K(x) \in (0,\infty)$. 
Then there exists a constant $C$, such that 
\begin{equation}\label{bd1}
u(x)\le C,\quad\forall \, x\in \Omega
\end{equation}
holds for all nonnegative solutions $u$ of \eqref{main2}.
\end{theorem}

To begin with, let us recall a classical result in
\cite{Rosoton2014Dirichlet}, in which the authors establish an optimal boundary regularity for the fractional equation with zero exterior Dirichlet condition.
\begin{proposition}[\cite{Rosoton2014Dirichlet}]\label{otonserra}
 Suppose $\Omega$ is a bounded Lipschitz domain with exterior ball condition, $g\in L^\infty(\Omega)$, $s\in (0,1)$, $u$ is a classical solution of the following Dirichlet problem:
 \begin{equation}\label{eq1}
 \begin{cases}
 \flap u = g,&\text{in } \Omega,\\
 u=0, &\text{in } \Omega ^c.\\
 \end{cases}
 \end{equation}
 Then $u\in C^{s}(\R^n)$ and 
\begin{equation}\label{hd}
 \norm{u}_{C^s(\R^n)}\le C\norm{g}_{L^\infty(\Omega)},
\end{equation}
where $C=C(n,s)$ is a positive constant.
\end{proposition}
Notice that here $\Omega$ is a {\em bounded domian}. In this situation, a supersolution and a subsolution can be constructed to show that the global $L^{\infty}$ norm of $u$ is bounded by $\norm{g}_{L^\infty(\Omega)}$ as the following. Let 
\[\psi(x):=(1-|x|^2)_+^s.\]
It is well known that 
\[\flap \psi (x)=a>0.\]
Choose $R$ sufficiently large, so that $\Omega\subset B_R(0).$ Denote
\[\bar{u}(x):=\norm{g}_{L^{\infty}(\Omega)}\frac{R^{2s}}{a}\psi_R(x), ~\mbox{with}~ \psi_R(x):={\psi(\frac{x}{R})}.\]
Then it can be easily verified that $\bar{u}$ and $-\bar{u}$ are super-solution and sub-solution of \eqref{eq1}, respectively. Therefore, 
\begin{equation*}
 \norm{u}_{L^{\infty}(\Omega)}\le C\norm{g}_{L^\infty(\Omega)},
\end{equation*}
From the above construction, one can see that in order to obtain \eqref{hd}, it is necessary that $\Omega$ be bounded.
When $\Omega$ is an {\em unbounded domain}, it is evident that the solution $u$ is required to be globally bounded. This requirement can not be fulfilled in the process of employing the blow-up and rescaling argument to obtain a priori estimates for solutions to a corresponding family of nonlinear fractional equations on {\em unbounded domains with boundaries}.

This motivates us to establish a local version of the boundary regularity, in which, instesd of global one, only a local ${L^{\infty}}$ norm of the solution is involved.
\begin{theorem}\label{bdry C^s}
 Suppose $\Omega$ is a unbounded domain with locally $C^{1,1}$ boundary, $0<s<1$, $g\in L^\infty(\Omega\cap B_4)$ and $u$ is a nonnegative classical solution of
 \begin{equation}
 \begin{cases}
 \flap u = g,&\text{in } \Omega\cap B_4,\\
 u=0, &\text{in } B_4\backslash \Omega.\\
 \end{cases}
 \end{equation}
 Then $u\in C^{s}(\Omega\cap B_{1/2})$ and 
 \[
 \norm{u}_{C^s(\Omega\cap B_{1/2})}\le C(\norm{g} _{L^\infty(\Omega\cap B_4)} + \norm{u} _{L^\infty(\Omega\cap B_4)} ),
 \]
 where $C$ depends on $n,s$ and $C^{1,1}_{loc}$ norm of $\partial\Omega$, and $B_r$ denotes a ball centered at any fixed point on the boundary $\partial\Omega$ with radius $r$.
\end{theorem}
The idea of the proof is that we divide the solution into two parts: the potential part and the harmonic part. The regularity for the potential part is obtained by Theorem \ref{otonserra}. For the harmonic part, we firstly derived an $\alpha$ power order decay near $\partial\Omega$, here $\alpha$ is a certain positive number which may be less than $s$. Combining the decay estimate and the interior regularity result (Theorem \ref{Holder thm}), we derive the $C^\alpha$ boundary regularity. Finally we refine the boundary regularity by an iteration progress.

To continue estimate $\norm{u}_{C^{\alpha_0}(\Omega\cap B_{1/2})}$, we need the interior H\"older estimate from \cite{chen2025refinedregularitynonlocalelliptic}.
\begin{proposition}[Interior H\"older regularity]\label{Holder thm}
 Assume $0<s<1$, and $u\in C^{1,1}_{loc}(\R^n)\cap \mathcal{L}_{2s}$ is a nonnegative solution of 
 \begin{equation}
 \flap u(x) = g(x),\quad x\in B_1
 \end{equation}
 where $g\in L^\infty(B_1)$. Then for any $0<\varepsilon <2s$,
 \begin{equation}
 \norm {u}_{C^{[2s-\varepsilon],\{2s-\varepsilon\}}(B_{1/2})}\le C(\norm{g}_{L^\infty(B_1)}+\norm{u}_{L^\infty(B_1)}).
 \end{equation}
\end{proposition}
Based on this, we arrive at
\begin{lemma}\label{global holder lemma}
 The decay estimate \eqref{decay estimate} and Proposition \ref{Holder thm} implies that 
 \begin{equation}
 \norm{u} _{C^{\alpha _0}(\Omega\cap B_{1/2})}\le C(\norm{u}_{L^\infty(\Omega\cap B_4)}+\norm{g}_{L^\infty(\Omega\cap B_4)})
 \end{equation}
 where $C$ depends on $s,n$, and $\norm{\partial \Omega}_{C^{1,1}_{loc}}$, $\alpha_0:=\min\{s,1-s\}\in (0,1/2)$. 
\end{lemma}

\section{Appendix}
Here is a generalization of \cite[Theorem 1.1]{Du2023blowup}Du-Jin-Xiong-Yang's convergence result.
\begin{theorem}
 Assume $n\ge 1$, $s\in (0,1)$, $\beta\in (0,1)$. $\Omega$ is an unbounded domain with boundary. Suppose nonnegative functions $\{u_i\}\subset \mathcal{L}_{2s}\cap C^{2s+\beta}_{loc}(\Omega)$ vanishes outside $\Omega$, and $u\in \mathcal{L}_{2s}$ vanishes outside $\Omega$. If $\{u_i\}$
 converges to a function $u\in \mathcal{L}_{2s}$ in $C^{2s+\beta}_{loc}(\Omega)$, and $\{\flap u_i \}$ converges pointwisely in $\Omega$, then there exists a constant $b\ge 0 $ such that
 \begin{equation}
 \lim _{i\to\infty}\flap u_i(x) = \flap u(x) -b.
 \end{equation}
\end{theorem}
\begin{proof}
 Fix any $x\in\Omega$, consider $R\gg|x|+1$.
 \begin{align*}
 \flap u(x)-\flap u_i(x) & = c_{n,s}\int _{B_R}\frac{(u-u_i)(x)-(u-u_i)(y)}{|x-y|^{n+2s}}dy \\ &+c_{n,s}\int _{B_R^c}\frac{(u-u_i)(x)-u(y)}{|x-y|^{n+2s}}dy\\
 & + c_{n,s}\int _{B_R^c}\frac{u_i(y)}{|x-y|^{n+2s}}dy\\
 & := A_i(x,R) + E_i(x,R) + F_i(x,R).
 \end{align*}
 For $E_i$, since $u\in \mathcal{L}_{2s}$, 
 \begin{equation}
 \lim _{R\to\infty}\lim _{i\to\infty}E_i(x,R) = -c_{n,s}\lim _{R\to\infty}\int _{B_R^c}\frac{u(y)}{|x-y|^{n+2s}}dy =0.
 \end{equation}
 The consideration of $A_i$ is a little bit different with that in \cite{Du2023blowup}. In our cases, $B_R$ is not contained in $\Omega$ for sufficiently large $R$. Fix $\varepsilon >0$ such that $B_\varepsilon(x)\subset \Omega$. Then
 \begin{align*}
 A_i(x,R) & = c_{n,s}\int _{B_R\backslash B_\varepsilon(x)}\frac{(u-u_i)(x)-(u-u_i)(y)}{|x-y|^{n+2s}}dy \\
 &+c_{n,s}\int _{B_\varepsilon(x)}\frac{(u-u_i)(x)-(u-u_i)(y)}{|x-y|^{n+2s}}dy
 \end{align*}
 By dominated convergence theorem, the first term converges to 0 as $i\to\infty$. For the second term,
 \[
 \lim _{i\to\infty} c_{n,s}\int _{B_\varepsilon(x)}\frac{(u-u_i)(x)-(u-u_i)(y)}{|x-y|^{n+2s}}dy\le c_{n,s}\lim _{i\to\infty}[u-u_i]_{C^{2s+\beta}(B_\varepsilon(x))}\varepsilon ^\beta = 0.
 \]
 Hence $\lim _{i\to\infty}A_i(x,R)=0$. Therefore 
 \begin{equation}
 \lim _{R\to\infty}\lim _{i\to\infty}A_i(x,R)=0.
 \end{equation}
 Then the same argument in \cite{Du2023blowup} implies $\lim _{i\to\infty}F_i(x,R)$ exists and
 \[
 \lim _{R\to\infty}\lim _{i\to\infty}F_i(x,R) =\lim _{R\to\infty}\lim _{i\to\infty}F_i(0,R) = :b\ge 0.
 \]
\end{proof}

selected.post_theorem_intro_text:
The idea of the proof is that we divide a given solution into two parts: the potential part and the harmonic part. The regularity for the potential part is obtained by Proposition \ref{otonserra}. For the harmonic part $h$, we rewrite it in terms of the Poisson representation formula in balls. Using this explicit expression, we  first carry out a detailed analysis to   derive an $\alpha$ power order decay near $\partial\Omega$,
\begin{equation*}
        |h(x)|\le C\{\lVertu\rVert_{L^\infty(\Omega \cap B_4)}+\lVertu\rVert_{\cL_{2s}}\}\operatorname{dist}(x,\partial \Omega)^{\alpha },
    \end{equation*}
    where $\alpha = \min\{s,1-s\}$. Combining this decay estimate and the interior regularity result (Theorem \ref{Holder thm}), we derive the $C^\alpha$ boundary regularity. Then by an iteration process, we increase the power $\alpha$ successively until it reaches the desired power $s$.

As an important application, we establish a priori estimate for the solutions  to \eqref{main2}.  We assume that $\Omega \subset \mathbb{R} ^n$ is an unbounded domain with uniformly $C^{1,1}$ boundary, and $f$ satisfies the following condition:
\begin{itemize}
    \item $f(x,t):\Omega \times [0,\infty)\to\mathbb{R}$ is uniformly H\"older continuous with respect to $x$ and continuous with respect to $t$.
\end{itemize}
\begin{theorem}\label{1A1}
Assume $1<p<\frac{n+2s}{n-2s}$, $f$ satisfies 
\begin{equation}\label{growth f}
    f(x,t)\le C_0(1+t^p)
\end{equation}
uniformly for all $x$ in $\Omega$, and 
\begin{equation}\label{lim f}
    \lim _{t\to\infty}\frac{f(x,t)}{t^p} = K(x),
\end{equation}
    where $K(x)\in (0,\infty)$ is uniformly continuous and $K(\infty):=\lim _{|x|\to\infty }K(x) \in (0,\infty)$. 
Then there exists a constant $C$, such that 
\begin{equation}\label{bd1}
u(x)\le C,\quad\forall \, x\in \Omega
\end{equation}
holds for all nonnegative solutions $u$ of \eqref{main2}.
\end{theorem}

\begin{remark}
    The assumptions on $f$ are essential for the a priori estimate. When $f=0$ and $\Omega = B_1$, Abatangelo, Jarohs and Salda\~na \cite{Abatangelo2018Green} constructed nontrivial nonnegative solutions to \eqref{main2} that are unbounded, see also \cite{Li2023unique}.
\end{remark}

During the process of blow-up and rescaling, it can be shown that a sequence of the rescaled functions (still denoted by $u_i$) converges to a limiting function $u$ in the sense of $C^{2s+\beta}_{loc}$. In the case of a local operator, say $-\Delta$, we already have 
\[   \lim _{i\to\infty}(-\Delta) u_i(x) = (-\Delta) u(x).\]
However, this is not the case for nonlocal operators, as shown in \cite[Theorem 1.1]{Du2023blowup} by Du-Jin-Xiong-Yang, in which they work on the whole space $\mathbb{R}^n$. In order to establish a priori estimate on general  unbounded domains with boundaries, we generalize  their convergence result as follows.
\begin{theorem}\label{conv}
    Assume $n\ge 1$, $s\in (0,1)$, $\beta\in (0,1)$. $\Omega$ is an unbounded domain with boundary. Suppose nonnegative functions $\{u_i\}\subset \mathcal{L}_{2s}\cap C^{2s+\beta}_{loc}(\Omega)$ vanishes outside $\Omega$, and $u\in \mathcal{L}_{2s}$ vanishes outside $\Omega$. If $\{u_i\}$
    converges in $C^{2s+\beta}_{loc}(\Omega)$ to a function $u\in \mathcal{L}_{2s}$ , and $\{\mbox{$(-\triangle)^s$} u_i \}$ converges pointwisely in $\Omega$, then there exists a constant $b\ge 0 $ such that
    \begin{equation}
        \lim _{i\to\infty}\mbox{$(-\triangle)^s$} u_i(x) = \mbox{$(-\triangle)^s$} u(x) -b.
    \end{equation}
\end{theorem}

 In Section 2, we establish local boundary H\"older regularity  for \eqref{main1} and prove Theorem \ref{1bdry C^s}. In Section 3, we derive  a priori estimates for \eqref{main2} and validate Theorem \ref{1A1}. Finally, the proof of Theorem \ref{conv} is included in the Appendix.

