theorem.content:
\label{katot}
For $s>\frac{3}{4}$, if $u_0 \in H^{s}\left(\mathbb R^{+}\right)$and $f \in H_{l o c}^{\frac{s+1}{3}}\left(\mathbb R^{+}\right)$ satisfy certain compatibility conditions at $(x,t)=(0,0)$, then the IBVP \eqref{IBVP} admits a unique solution
$$
u \in C\left(0, T ; H^{s}\left(\mathbb R^{+}\right)\right) \cap L^{2}\left(0, T ; H_{l o c}^{s+1}\left(\mathbb R^{+}\right)\right),
$$
which satisfies the additional properties

\begin{equation}\label{reg-trace}
\partial_x^ju \in C(\mathbb R^+; H^{\frac{s-j+1}{3}}((0,T))),\ j\in \{0,1,2,3,...\};
\end{equation}
\begin{equation}\label{kato}\left(\sup _{0<x<+\infty} \int_{0}^{T}\left|\partial_{x}^{s+1} u(x, t)\right|^{2} d t\right)^{\frac{1}{2}} \leq C\left(\|u_0\|_{H^{s}\left(\mathbb R^{+}\right)}+\|f\|_{H^{\frac{s+1}{3}}(0, T)}\right);
\end{equation}
\begin{equation}\label{stri}
\left(\int_{0}^{T} \sup _{0<x<+\infty}\left|\partial_{x} u(\cdot, t)\right|^{4} d t\right)^{\frac{1}{4}} \leq C\left(\|u_0\|_{H^{s}(\mathbb R^+)}+\|f\|_{H^{\frac{s+1}{3}}(0, T)}\right)
\end{equation}
and
\begin{equation}
\left(\int_{0}^{+\infty} \sup _{0 \leq t \leq T}|u(x, t)|^{2} d x\right)^{\frac{1}{2}} \leq C\left(\|u_0\|_{H^{s}(\mathbb R^+)}+\|f\|_{H^{\frac{s+1}{3}}(0, T)}\right),
\end{equation}
where the constants depend only on $s$ and $T$.

