satisfies $\Psi_n = M_{n,E} (\theta) \Psi_0$. The model~\eqref{eq:BVsys} was studied systematically by S.~Klein~\cite{SK_block}, and Duarte and Klein~\cites{DK1, DK2} within a very general framework, including the identically singular case when $\det B(\theta)\equiv 0$ on $\mathbb T^k$, $k\geq 1$. These models generalize the quasi-periodic Schr\"odinger Hamiltonians on a strip considered by Bourgain and Jitomirskaya~\cite{BJ}, who proved localization perturbatively for large disorder.

Since $M_E(\theta)$ is (complex) symplectic, see \eqref{def:symp}, for $\theta\in \mathbb T$, the Lyapunov exponents $\{L_j(\omega,M_E)\}_{j=1}^{2d}$, see definition in \eqref{def:LE}, satisfy $L_{2d+1-j}=-L_j$ for $1\le j\le d$. 
Let $L^d(\omega,M_E)$ be the sum of the top $d$ Lyapunov exponents, and let $\kappa^d(\omega,M_E)$ be the acceleration, defined to be the right-derivative of $L^d(\omega,M_E(\cdot+i\varepsilon))$ in the imaginary direction $\varepsilon$, see \eqref{eq:acc}.

Throughout the paper we shall fix an energy $E_0\in \mathbb R$ such that $L_d(\omega,E_0)\geq \tau>0$. It is known, see \cite{AJS}, that $L^d(\omega,M_E(\cdot+i\varepsilon))$ and $L_d(\omega,M_E)$ are continuous in $E,\varepsilon$ and $\kappa^d(\omega,M_E)$ is upper semi-continuous in $E,\varepsilon$, hence we can assume that in a neighborhood $I_{E_0}$ of $E_0$, the following holds uniformly in $E\in I_{E_0}$ and $|\varepsilon|\leq \delta$, $\varepsilon\in \mathbb R$, for some $\delta=\delta(E_0)>0$:
\begin{align}\label{def:IE0}
\begin{cases}
L_d(\omega,M_E(\cdot+i\varepsilon))\geq \tau/2,\\
\kappa^d(\omega,M_E(\cdot+i\varepsilon))\leq \kappa^d(\omega,M_{E_0})\\
L^d(\omega,M_E(\cdot+i\varepsilon))\leq L^d(\omega,M_E)+2\pi \kappa^d(\omega,M_{E_0})\varepsilon.
\end{cases}
\end{align}
Note the third inequality is a corollary of the second one.

The density of states $\mathcal{N}(\omega,\cdot)$ is the limiting cumulative distribution function of the finite-volume eigenvalues. 
Let $H_{\omega,\theta}|_{\Lambda}$ be the restriction of $H_{\omega,\theta}$ to the interval $\Lambda=[a,b]\subset \mathbb Z$.
Let $\{E_{\Lambda,j}(\omega,\theta)\}_{j=1}^{|\Lambda|}$ be the eigenvalues of $H_{\omega,\theta}|_{\Lambda}$.
Consider
\begin{align}
 N_{\Lambda}(\omega,E,\theta):=\frac{1}{|\Lambda|}\sum_{j=1}^{|\Lambda|}\chi_{(-\infty,E)}(E_{\Lambda,j}(\omega,\theta)).
\end{align}
It is well-known that the weak-limit
\begin{align}
 \lim_{a\to-\infty, b\to \infty}\mathrm{d} N_{\Lambda}(\omega,E,\theta)=:\mathrm{d} \mathcal{N}(\omega,E).
\end{align}
exists and is independent of $\theta$. In this paper we prove the following result.

\begin{align}\label{def:LE}
L_j(\omega, A,n):=\frac{1}{n}\int_{\T} \log \sigma_j(A_n(\omega,\theta))\, \mathrm{d}\theta, \text{ for } 1\leq j\leq k,
\end{align}

\begin{align}\label{def:symp}
    M^*\Omega M=\Omega,
\end{align}

\begin{equation}\label{eq:BVsys}
   (H_{\omega,\theta} \Phi)_n   = B_{n+1}(\theta)\Phi_{n+1}+ B_n^{(*)}(\theta) \Phi_{n-1}+ V_n (\theta)\Phi_n
\end{equation}

\begin{align}\label{eq:acc}
\kappa^1_{\varepsilon}(\omega, A):=\lim_{\varepsilon'\to 0^+} \frac{L^1_{\varepsilon+\varepsilon'}(\omega, A)-L^1_{\varepsilon}(\omega, A)}{2\pi \varepsilon'}.
\end{align}

In \cite{HS3}*{Lemma 2.8} we established the following large deviation theorem for $f_n$.
\begin{lemma}\label{lem:deno}
Let $\omega\in \mathrm{DC}$, and $\gamma>0$ be as in Lemma \ref{lem:LDTsig}.
Assume $L_d(\omega,M_E)\geq \nu>0$.
There exist $\gamma>0$, $N_0>1$ large and $0<\kappa_0\ll 1$ so that the {\it $\kappa_0$-admissible} sequence 
\begin{align}\label{def:admissible}
\mathcal{N}:=\{n\geq N_0: \|n\omega\|_{\T}\leq \kappa_0\}
\end{align}
has the following property: 
for any $|\varepsilon|\leq \delta/2$, and all large $\kappa_0$-admissible $n$, the following large deviation set 
\begin{align}\label{def:B_fEn}
\mathcal{B}_{f,E,n,\varepsilon}:=
\big\{\theta\in \T: n^{-1}\log |f_{n}(\theta+i\varepsilon,E)|<\langle \log |\det B(\cdot+i\varepsilon)|\rangle +{L}^d_{\varepsilon}(\omega,M_E)- n^{-\gamma}\big\}
\end{align}
satisfies $\mathrm{mes}(\mathcal{B}_{f,E,n,\varepsilon})<e^{-n^{\gamma}}$.
\end{lemma}
\begin{remark}\label{rem:admissible}
 For every large integer $n>0$ there exists an admissible $\tilde n>0$ with $|n-\tilde n|\le C_*$ for some constant $C_*$.
\end{remark}

Recall that $E\in I_{E_0}$.
Our goal is to analyze the following for an arbitrary fixed $\theta$ as $N\to\infty$:
\begin{align}\label{eq:goal}
 &d_{\omega,N}(\theta,E-\eta,E+\eta)=\frac{1}{N}\mathrm{tr}(P_{[E-\eta, E+\eta)}(H_{\omega,\theta}|_{[0,N-1]})),
\end{align}
in which $H_{\omega,\theta}|_{[0,N-1]}$ is $H_{\omega,\theta}$ restricted to the interval $[0,N-1]$ with Dirichlet boundary condition and $P_{[E-\eta,E+\eta)}$ stands for the spectral projection.
Bounding \eqref{eq:goal} through the trace of the resolvent yields
\begin{align}\label{eq:dN<G}
 d_{\omega,N}(\theta,E-\eta,E+\eta)
 &\leq \frac{2\eta}{N} \mathrm{Im}(\mathrm{tr}(G_{[0,N-1]}^{E+i\eta}(\theta)))\\
 &=\frac{2\eta}{N}\sum_{k=0}^{N-1} \mathrm{Im} (G_{[0,N-1]}^{E+i\eta}(\theta;k,k)),
\end{align}
in which $G^{E+i\eta}_{[0,N-1]}(\theta)=(H_{\omega,\theta}|_{[0,N-1]}-(E+i\eta))^{-1}$ is the Green's function, i.e., the kernel of the resolvent.
Let an auxiliary parameter $\tau$ be defined as
\begin{align}\label{eq:choose_tau}
 \tau=\eta^{\frac{1}{2\kappa}}.
\end{align}
For any $n\in \N$, let 
\begin{align}
 \mathcal{B}_{n,h}^{\eta}:=\{\theta\in \T: u_n(e^{2\pi i\theta},E+i\eta)<L(E,n)-h\cdot n^{-\gamma}\}.
\end{align}
be the large deviation set for $u_n(z,E+i\eta)=n^{-1}\log |D_n(z,E+i\eta)|$. 
We choose $m\in \N$ such that
$e^{-(2m)^{\gamma_1}}\simeq \eta$.
The set $\mathcal{B}_{2m,2}^{\eta}$ satisfies a large deviation estimate
\begin{align}\label{eq:mes_B2m_2}
 \mes\;\mathcal{B}_{2m,2}^{\eta}\leq e^{-(2m)^{\gamma}}.
\end{align}
In fact, the large deviation estimate of Lemma \ref{lem:un_LDT} applies directly to $\mathcal{B}_{2m,1}^0$, implying that
\begin{align}\label{eq:mes_B2m_1}
 \mathrm{mes}\; \mathcal{B}_{2m,1}^0\leq e^{-(2m)^{\gamma}}.
\end{align}
If $\theta\in (\mathcal{B}_{2m,1}^0)^c$, $|D_{2m}(e^{2\pi i\theta},E)|>\exp(2m(L(E,2m)-(2m)^{-\gamma}))$. A telescoping argument, as in the proof of Lemma \ref{lem:un_lower_zeros_eta}, using that $\gamma_1>1-\gamma/2$, yields
\begin{align}
 |D_{2m}(e^{2\pi i\theta},E+i\eta)|>\frac{1}{2}|D_{2m}(e^{2\pi i\theta},E)|>\frac{1}{2}\exp(2m(L(E,2m)-(2m)^{-\gamma})).
\end{align}
This implies $(\mathcal{B}_{2m,1}^0)^c\subset (\mathcal{B}_{2m,2}^{\eta})^c$,
and hence \eqref{eq:mes_B2m_2}, when combining with \eqref{eq:mes_B2m_1}.

The proof is analogous to the scalar-valued case. 
Our goal is to estimate the following expression for arbitrary fixed $E\in I_{E_0}$ and $\theta\in \T$ as $N\to\infty$:
\begin{align}\label{eq:goal*}
 &d_{\omega,dN}(\theta,E-\eta,E+\eta)=\frac{1}{dN}\mathrm{tr}(P_{[E-\eta, E+\eta)}(H_{\omega,\theta}|_{[0,dN-1]})),
\end{align}
cf.\ \eqref{eq:goal}. As before, we 
bound~\eqref{eq:goal*} through the trace of the Green's function: 
\begin{align}\label{eq:dN<G*}
 d_{\omega,dN}(\theta,E-\eta,E+\eta)
 &\leq \frac{2\eta}{dN} \mathrm{Im}(\mathrm{tr}(G_{[0,dN-1]}^{E+i\eta}(\theta)))\\
 &=\frac{2\eta}{dN}\sum_{k=0}^{dN-1} \mathrm{Im} (G_{[0,dN-1]}^{E+i\eta}(\theta;k,k)),
\end{align}
in which $G^{E+i\eta}_{[0,dN-1]}(\theta)=(H_{\omega,\theta}|_{[0,dN-1]}-(E+i\eta))^{-1}$ is the kernel of the resolvent.
Let the auxiliary parameter $\tau$ be defined as 
\begin{align}\label{def:tau_d}
 \tau=\eta^{\frac{1}{2\kappa^d}},
\end{align}
in this block-valued case.
For any $\kappa_0$-admissible $n\in \N$, let 
\begin{align}
 \mathcal{B}_{n,h}^{\eta}:=\{\theta\in \T: u_n(e^{2\pi i\theta},E+i\eta)<L^d(E,n)+\langle \log |\det B(\cdot)|\rangle-h\cdot n^{-\gamma}\}
\end{align}
be the large deviation set for $u_n(z,E+i\eta)=n^{-1}\log |f_n(z,E+i\eta)|$. 
We choose $m\in \N$ such that $2m$ is $\kappa_0$-admissible and $e^{-(2m)^{\gamma_1}}\simeq \eta$. 
The set $\mathcal{B}_{2m,2}^{\eta}$ satisfies a large deviation estimate
\begin{align}\label{eq:B2m_eta_block}
 \mes\,\mathcal{B}_{2m,2}^{\eta}\leq e^{-(2m)^{\gamma}}.
\end{align}
In fact, note $2m$ is $\kappa_0$ admissible, the large deviation estimate of Lemma \ref{lem:deno} applies to $\mathcal{B}_{2m,1}^0$ implying
\begin{align}\label{eq:B2m_0_block}
 \mathrm{mes}\,\mathcal{B}_{2m,1}^0\leq e^{-(2m)^{\gamma}}.
\end{align}
Suppose $\theta\in (\mathcal{B}_{2m,1}^0)^c$, then
\begin{align}
 |f_{2m}(e^{2\pi i\theta},E)|\geq \exp(2m(L^d(E,2m)+\langle \log |\det B(\cdot) |\rangle-(2m)^{-\gamma})).
\end{align}
By the same telescoping argument in the proof of Lemma \ref{lem:un_lower_zeros_eta*}, using, $\gamma_1>1-\gamma/2$, we have
\begin{align}
 |f_{2m}(e^{2\pi i\theta},E+i\eta)|\geq \frac{1}{2} |f_{2m}(e^{2\pi i\theta}, E)|\geq \exp(2m(L^d(E,2m)+\langle \log |\det B(\cdot) |\rangle-2(2m)^{-\gamma})).
\end{align}
This implies $(\mathcal{B}_{2m,1}^0)^c\subset (\mathcal{B}_{2m,2}^{\eta})^c$, hence the estimate \eqref{eq:B2m_eta_block} follows from \eqref{eq:B2m_0_block}.
Let $\{\xi_j\, e^{2\pi i\theta_j}\}_{j=1}^{J_0}$, $\xi_j>0$ and $\theta_j\in \T$, be the zeros of $f_{2m}(z,E+i\eta)$. 
Cartan's estimate implies that 
\begin{align}\label{eq:B2m_theta_pm_rm*}
\mathcal{B}_{2m,m^{\gamma/2}}^{\eta}\subset \bigcup_{j=1}^{J_0}(\theta_j-\tilde{r}_m, \theta_j+\tilde{r}_m),
\end{align}
with $\tilde{r}_m:=e^{-cm^{\gamma/2}}$ for some constant $c>0$, and $J_0\lesssim m$.
Applying Lemma~\ref{lem:un_lower_zeros_eta*} to $n=2m$ and $z_0=e^{2\pi i\theta_j}$, for each $1\leq j\leq J_0$, yields the existence of $|k_j|<(1-\varepsilon)m$, $C_j\in [1,2\kappa^d+1]$, and $\ell_j\in [1,2\kappa^d]$, such that $w_j(z):=f_{2m}(z e^{2\pi ik_j\omega},E+i\eta)$
has $\ell_j$ zeros in $B(e^{2\pi i\theta_j}, (4C_j+1)r_m)$, $r_m\simeq \exp(-(\log m)^{C_0})\gg \tilde{r}_m$.
Denoting the zeros of $f_{2m}(z e^{2\pi ik_j\omega},E+i\eta)$ by $\{\xi_{j,\ell}\, e^{2\pi i\theta_{j,\ell}}\}_{\ell=1}^{\ell_j}$ by $\xi_{j,\ell}>0$, $\theta_{j,\ell}\in \T$, one has
\begin{align}\label{eq:wj_lower_zeros*}
 \log |w_j(z)|\geq 2m(L^d(E,2m)+\langle \log |\det B(\cdot)|\rangle-m^{-\gamma/2})+\sum_{\ell=1}^{\ell_j}\log |z-\xi_{j,\ell}\, e^{2\pi i\theta_{j,\ell}}|,
\end{align}
for all $z\in B(e^{2\pi i\theta_j},(4C_j+2)r_m)$.
For each $1\leq j\leq J_0$ and $1\leq \ell\leq \ell_j$, let 
 $ \tilde{I}_j, 
 I_{j,\ell}$ be defined as in~\eqref{eq:Ijdef}. 
With $\tau$ as in \eqref{eq:choose_tau} and $\tau\ll r_m$, we have for each $j,\ell$ that $I_{j,\ell}\subset \tilde{I}_j$.
As before, we let $\tilde{\mathcal{B}}_{2m}^{\eta}:=\bigcup_{j=1}^{J_0} \tilde{I}_j$. 
Clearly, by \eqref{eq:B2m_theta_pm_rm*}, $\mathcal{B}_{2m,m^{\gamma/2}}^{\eta}\subset \tilde{\mathcal{B}}_{2m}^{\eta}$.
We again divide the analysis of $G^{E+i\eta}_{[0,dN-1]}(\theta; k,k)$ into three cases.

